<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();$q=$pdo->prepare('SELECT * FROM users WHERE user_id=? LIMIT 1');$q->execute([(int)$_SESSION['admin_id']]);$u=$q->fetch();$errors=[];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');if(!$u||!password_verify($old,$u['password_hash']))$errors[]='Current management password is incorrect.';elseif(strlen($new)<8)$errors[]='New password must be at least 8 characters.';elseif($new!==$confirm)$errors[]='Passwords do not match.';elseif($old===$new)$errors[]='New password must be different from the current password.';else{$pdo->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE user_id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$u['user_id']]);$msg='Password changed successfully. Your current management session remains active.'; audit_log('CHANGE MANAGEMENT PASSWORD','Self-service password change');}}$title='Change Management Password';require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a class="active" href="/admin/settings.php">Settings</a><a href="/admin/users.php">Admin & Staff</a><a href="/auth/logout.php">Sign out</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">ACCOUNT SECURITY</span><h1>Change password</h1><p>Verify your current password before creating a new secure management password.</p></div></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($errors):?><div class="errors"><?=e($errors[0])?></div><?php endif;?><section class="panel narrow"><form method="post" class="form"><?=csrf_field()?><label>Current password<input type="password" name="old_password" autocomplete="current-password" required></label><label>New password<input type="password" name="new_password" minlength="8" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" autocomplete="new-password" required></label><button class="btn primary">Change password</button></form></section></section></div><?php require __DIR__.'/../includes/footer.php';?>
